import{_ as r,a,b as s,c as n,d,e as l,f as p}from"./chunks/OOP_UI3.DGHtp2cm.js";import{_ as c,C as u,o as m,c as b,a3 as i,j as e,E as O,w as h}from"./chunks/framework.g9mfNVRQ.js";const y=JSON.parse('{"title":"Algoritmo esterno (OOP)","description":"","frontmatter":{"source_hash":"bb1a1f1faf","source_commit":"7a18e7c"},"headers":[],"relativePath":"it/use/OOP.md","filePath":"it/use/OOP.md"}'),g={name:"it/use/OOP.md"};function f(v,t,_,P,L,z){const o=u("big");return m(),b("div",null,[t[1]||(t[1]=i('<p>Gli algoritmi Out of process sono app esterne che si occupano di un&#39;elaborazione dei dati non fornita direttamente da xDrip.</p><p>Oggi sono usati solo per i sensori Libre e i bridge.</p><p>Esistono due famiglie di algoritmi Out Of Process (OOP):</p><h3 id="oop1" tabindex="-1">OOP1 <a class="header-anchor" href="#oop1" aria-label="Permalink to &quot;OOP1 {#oop1}&quot;">​</a></h3><img src="'+r+'" style="zoom:75%;"><div class="warning custom-block"><p class="custom-block-title">SOLO versioni di Android vecchie</p><p>La versione massima di Android supportata è la 9.<br> È stato segnalato che alcuni telefoni con Android 10 e successivi funzionano con OOP1new/OOP1us.</p></div><table tabindex="0"><thead><tr><th>Versione OOP</th><th>Data versione</th><th>Sensori supportati</th><th>Dimensione file</th></tr></thead><tbody><tr><td>OOP1 (2bb9458)</td><td>2018-08-26</td><td>Libre</td><td>17.1MB</td></tr><tr><td>OOP1new (fa218ef)</td><td>2019-11-22</td><td>Libre, Libre 2 EU</td><td>25.3MB</td></tr><tr><td>OOP1us (e901151) - <strong>non usare: usa OOP2</strong></td><td>2019-09-13</td><td>Libre 14 days US (vecchio)</td><td>27.8MB</td></tr></tbody></table><p>OOP1 fornisce letture simili a quelle del lettore del produttore, senza calibrazione. Ti serve un <a href="./../install/libreBT.html">bridge compatibile</a>, se ne usi uno. OOP1 si applica anche ai risultati delle scansioni NFC.</p><div class="warning custom-block"><p class="custom-block-title">Nessuna calibrazione possibile</p><p>Con OOP1 le calibrazioni vengono ignorate.<br> È una funzione di sicurezza, perché xDrip non può verificare la plausibilità dei dati forniti da OOP1.</p></div><p>Sono disponibili due versioni: <a href="https://drive.google.com/open?id=13ERWcSVSFMLy9rhpbv5rArFrnDuAzriM" target="_blank" rel="noreferrer">Libre 1 e Libre 2 EU</a> oppure <a href="https://drive.google.com/open?id=172whZZYTyE_ZEuN0T-zhdMKhucy6jP-a" target="_blank" rel="noreferrer">Libre 14 Days US</a>. <em>Nota: devi aver effettuato l&#39;accesso al tuo account Google per aprire i link qui sopra</em></p><p>Quando usi OOP1, l&#39;algoritmo Out Of Process deve essere <a href="./misc.html#out-of-process-algorithm">attivato</a>.</p><h3 id="oop2" tabindex="-1">OOP2 <a class="header-anchor" href="#oop2" aria-label="Permalink to &quot;OOP2 {#oop2}&quot;">​</a></h3><img src="'+a+'" style="zoom:75%;"><p>OOP2 fornisce la decodifica per i sensori Libre 14 days US e Libre 2 EU, sia in connessione diretta (solo Libre 2 EU) sia tramite un <a href="./../install/libreBT.html">bridge compatibile</a>.</p><div class="info custom-block"><p class="custom-block-title">La calibrazione è facoltativa</p><p>Puoi calibrare a partire dai dati grezzi, non calibrare oppure aggiungere una calibrazione ai dati nativi.<br> Consulta le <a href="./misc.html#oop2">impostazioni OOP2</a>.</p></div><p><strong>Usa solo l&#39;app OOP2 più recente con la versione più recente di xDrip.</strong></p>',16)),e("p",null,[e("strong",null,[e("u",null,[O(o,null,{default:h(()=>[...t[0]||(t[0]=[e("a",{href:"https://drive.google.com/file/d/1106h2s12b3Ev9gKCTU2G75q8h9ChHjcz/view?usp=sharing",target:"_blank",rel:"noreferrer"},"→ Scarica qui l'ultima OOP2. ←",-1)])]),_:1})])])]),t[2]||(t[2]=i('<p><em>Nota: devi aver effettuato l&#39;accesso al tuo account Google per aprire il link qui sopra.</em></p><div class="warning custom-block"><p class="custom-block-title">Attenzione</p><p>Quando usi OOP2, <em>Out Of process Libre Algorithm</em> (OOP1) deve essere <a href="./misc.html#out-of-process-algorithm">disattivato in xDrip</a>.</p></div><table tabindex="0"><thead><tr><th>Versione OOP</th><th>Data versione</th><th>Sensori supportati</th><th>Dimensione file</th></tr></thead><tbody><tr><td>OOP2 (70129ac) - <strong>non usare</strong></td><td>2021-12-04</td><td>Libre 2 EU</td><td>2.63MB</td></tr><tr><td>OOP2new (93e5cac) - <strong>non usare</strong></td><td>2020-12-08</td><td>Libre 14 days US, Libre 2 EU</td><td>2.65MB</td></tr><tr><td>OOP2 1.2 (8a0ee8f) - <strong>non usare</strong></td><td>2022-06-10</td><td>Libre 14 days US (vecchio), Libre 2 EU</td><td>2.66MB</td></tr><tr><td>OOP2_e6 (6de6678) - <strong>non usare</strong></td><td>2023-01-10</td><td>Libre 14 days US (nuovo), Libre 2 EU</td><td>2.66MB</td></tr><tr><td>OOP2_more (27da3f5)</td><td>2023-05-25</td><td>Libre 14 days US (nuovo), Libre 2 EU (nuovo)</td><td>2.66MB</td></tr><tr><td>OOP2_c6_09_31 (27da3f5)</td><td>2024-05-31</td><td>Libre 14 days US, Libre 2/2+ EU</td><td>2.7MB</td></tr><tr><td>OOP2-7f0e31 (27da3f5)</td><td>2025-06-12</td><td>Libre 14 days US, Libre 2/2+ EU</td><td>2.73MB</td></tr><tr><td><strong>OOP2-21_9_25 (05d1989)</strong></td><td><strong>2025-09-21</strong></td><td><strong>Libre 14 days US, Libre 2/2+ EU</strong></td><td><strong>2.73MB</strong></td></tr></tbody></table><h3 id="auto-detection" tabindex="-1">Rilevamento automatico <a class="header-anchor" href="#auto-detection" aria-label="Permalink to &quot;Rilevamento automatico {#auto-detection}&quot;">​</a></h3><p>Alcune versioni più vecchie di xDrip rilevano la presenza o la necessità dell&#39;algoritmo out of process.</p><p>Attivalo <u>solo</u> per OOP1.<br><strong>Non attivarlo per OOP2</strong>. Se l&#39;hai attivato per errore, <a href="./misc.html#out-of-process-algorithm">disattiva</a> OOP1.</p><img src="'+s+'" style="zoom:75%;"><h3 id="settings" tabindex="-1">Impostazioni <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Impostazioni {#settings}&quot;">​</a></h3><p>Use service corrisponde ad accendere o spegnere l&#39;app OOP. Se vuoi usarla, deve essere attivato.</p><img src="'+n+'" style="zoom:75%;"><p>Foreground service è un&#39;aggiunta che riduce la probabilità che il telefono metta l&#39;app in sospensione. Non impedisce però a Google Play Protect di fermarla.<br> Attivalo se hai perdite di dati (<strong>consigliato</strong>).</p><img src="'+d+'" style="zoom:75%;"><p>Direct intent può essere attivato se il tuo smartwatch Wear OS autonomo lo richiede (serve un bridge).</p><img src="'+l+'" style="zoom:75%;"><p>Puoi selezionare l&#39;intervallo con cui OOP verifica di essere disponibile.<br> Se hai perdite di dati puoi ridurre l&#39;intervallo. Più breve è l&#39;intervallo, maggiore sarà il consumo di batteria.</p><img src="'+p+'" style="zoom:75%;"><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2024.11.26" target="_blank" rel="noreferrer"><em>Ultima modifica 15/12/2024</em></a></p>',18))])}const E=c(g,[["render",f]]);export{y as __pageData,E as default};
